// 行动冻结条款独立重建作者配额；同时篡改params和fact也不能减免装备或侵占另一预留。
#include "military_model.hpp"
#include "military_lifecycle.hpp"
#include "training_rules.hpp"
#include "military_equal.hpp"
#include "resident/model/common_model.hpp"
#include "resident/storage/common_store.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {
namespace {
template<class T> const T* get(const std::vector<T>& rows,const StableId& id){for(auto& r:rows)if(r.id==id)return &r;return nullptr;}
bool unique(const std::vector<StableId>& ids){for(auto& id:ids)if(id.empty())return false;return std::set<StableId>(ids.begin(),ids.end()).size()==ids.size();}
void add(std::vector<std::pair<StableId,Integer>>& goods,const StableId& id,Integer amount){for(auto& row:goods)if(row.first==id){row.second+=amount;return;}goods.emplace_back(id,amount);}
// 字典规则相等不要求保存的键序相同；插入序仍在本记录和codec中独立保全。
bool same_goods(std::vector<std::pair<StableId,Integer>> a,std::vector<std::pair<StableId,Integer>> b){std::sort(a.begin(),a.end());std::sort(b.begin(),b.end());return a==b;}
Status formation(const CommonRead& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitaryAccess& access,const ArmyFormationTerms& terms,const ArmyForm& request){
    auto campaign=get(s.campaigns,terms.order_id);auto office=get(cat.offices,terms.office_id);if(!campaign||!office||terms.office_id!=campaign->office_id||terms.garrison_id!=campaign->garrison_id||terms.actor_id!=campaign->actor_id||request.order_id!=terms.order_id||!request.unit_ids_valid||request.unit_ids!=terms.unit_ids)return common_failure("MilitaryFormationOrderMismatch");auto camp=get(cat.garrisons,terms.garrison_id);if(!camp||terms.organization_id!=office->organization_id||terms.garrison_id!=office->garrison_id||(office->command_scope=="unit"&&terms.unit_ids.size()!=1))return common_failure("MilitaryCommandScope");if(terms.place_id!=camp->place_id||terms.organization_id!=camp->organization_id||!terms.ownership_id.empty()||terms.commanders.size()!=terms.unit_ids.size())return common_failure("InvalidMilitaryFormationTerms");
    std::vector<StableId> people{terms.actor_id};std::vector<std::pair<StableId,Integer>> goods;Integer mouths=0;for(std::size_t index=0;index<terms.unit_ids.size();++index){auto unit=get(s.military_units,terms.unit_ids[index]);if(!unit)return common_failure("InvalidArmyFormation");StableId commander;for(auto& pair:terms.commanders)if(pair.first==unit->id)commander=pair.second;auto expected=index==0?terms.actor_id:unit->commander_actor_id;if(!c.actor(commander)||commander!=expected||(index>0&&std::find(people.begin(),people.end(),commander)!=people.end())||unit->garrison_id!=camp->id||unit->organization_id!=camp->organization_id)return common_failure("MilitaryCommanderMismatch");if(index>0)people.push_back(commander);Integer count=unit->fit.size()+unit->wounded.size();mouths+=count;if(index==0)count+=terms.retainers.size();auto source=get(cat.garrisons,unit->source_garrison_id);auto definition=source?get(source->units,unit->id):nullptr;if(!definition)return common_failure("MilitaryUnitSourceMissing");for(auto& e:definition->equipment)add(goods,e.item_id,count*e.quantity_per_person);}
    auto named=request.retainer_ids;std::vector<StableId> pledged;for(auto& pledge:terms.retainers)pledged.push_back(pledge.actor_id);std::sort(named.begin(),named.end());std::sort(pledged.begin(),pledged.end());if(!request.retainer_ids_valid||!unique(request.retainer_ids)||named!=pledged)return common_failure("MilitaryRetainerTermsMismatch");for(auto& person:request.retainer_ids){const RetainerRecord* pledge=nullptr;for(auto& r:terms.retainers)if(r.actor_id==person)pledge=&r;if(!pledge||pledge->unit_id!=terms.unit_ids[0]||std::find(people.begin(),people.end(),person)!=people.end())return common_failure("MilitaryRetainerTermsMismatch");if(!access.retainer_source)return military_capability_failure("validate_profile","army_pledge",person);auto source=access.retainer_source(person,terms.order_id);if(!source||source->estate_id!=pledge->estate_id||source->source_id!=pledge->source_id)return common_failure("PrivateRetainerConsentRequired");people.push_back(person);}if(terms.member_actor_ids!=people)return common_failure("MilitaryParticipantsMismatch");mouths+=people.size();Integer quantity=request.food_quantity.value_or(mouths*camp->ration_per_person*2);if(!request.food_quantity_valid||!request.money_valid||quantity<0||quantity>1000000||terms.money<0||terms.money>1000000||terms.money!=request.money.value_or(0))return common_failure("InvalidMilitarySupplyTerms");if(quantity>0)add(goods,camp->food_item_id,quantity);if(!same_goods(terms.goods,goods))return common_failure("MilitaryEquipmentTermsMismatch");return common_success();
}
}
Status validate_military_action(const CommonRead& c,const MilitaryState& s,const MilitaryCatalog& cat,const MilitaryAccess& access,const ActionCoreView& action,bool finishing){
    if(action.kind=="military_train")return validate_military_training_action(c,s,cat,access,action);

    if(action.kind=="army_return"||action.kind=="army_resupply")return validate_military_logistics(c,s,cat,access,action,finishing);

    if(action.kind!="office_accept"&&action.kind!="army_form")return common_failure("InvalidMilitaryAction");const MilitaryActionPayload* payload=nullptr;for(auto& p:s.actions)if(p.action_id==action.id)payload=&p;auto fact=get(s.action_facts,action.id);if(!fact||fact->command!=action.kind||fact->actor_id!=action.actor_id||fact->start_tick!=action.start_tick)return common_failure("MilitaryActionFactMismatch");if(fact->phase=="completed"){if(!finishing)return common_failure("MilitaryActionAlreadyCompleted");return fact->completed_tick==action.start_tick+1&&fact->completed_tick<=c.tick()+1?common_success():common_failure("MilitaryActionAlreadyCompleted");}
    if(!payload||!same_terms(fact->terms,payload->terms)||!same_context(fact->context,payload->context))return common_failure("MilitaryActionFactMismatch");if(fact->phase!="started"||fact->completed_tick!=-1||fact->success||fact->result||action.remaining_ticks<(finishing?0:1)||action.remaining_ticks>1)return common_failure("InvalidMilitaryActionPhase");if(!finishing&&action.start_tick+1-action.remaining_ticks!=c.tick())return common_failure("MilitaryActionClockMismatch");std::vector<StableId> expected;
    if(action.kind=="office_accept"){auto terms=std::get_if<OfficeTerms>(&payload->terms);auto request=std::get_if<OfficeAccept>(&payload->request);if(!terms||!request||terms->actor_id!=action.actor_id||!payload->context||payload->context->input_error)return common_failure("InvalidMilitaryTerms");auto office=get(cat.offices,terms->office_id);auto role=office&&access.interaction_catalog&&access.interaction_catalog->common?access.interaction_catalog->common->roles.find(office->appointing_role_id):nullptr;if(!office||!c.actor(terms->provider_actor_id)||terms->provider_actor_id==action.actor_id||terms->provider_actor_id!=payload->context->provider_actor_id)return common_failure("InvalidOfficeAppointment");if(terms->organization_id!=office->organization_id||payload->context->role_id!=office->appointing_role_id||payload->context->place_id!=terms->place_id||!role||role->place_id!=terms->place_id)return common_failure("OfficeAppointmentAuthorityMismatch");expected={action.actor_id,terms->provider_actor_id};
    }else{
        auto terms=std::get_if<ArmyFormationTerms>(&payload->terms);auto request=std::get_if<ArmyForm>(&payload->request);if(!terms||!request||terms->actor_id!=action.actor_id)return common_failure("InvalidMilitaryTerms");if(!get(s.campaigns,terms->order_id)||!unique(terms->unit_ids)||terms->unit_ids.empty()||!unique(terms->member_actor_ids))return common_failure("InvalidArmyFormation");for(auto& id:terms->unit_ids){auto unit=get(s.military_units,id);if(!unit||unit->mobilizing_action_id!=action.id||!unit->army_id.empty())return common_failure("MilitaryUnitReservationMismatch");}auto formed=formation(c,s,cat,access,*terms,*request);if(!formed.ok)return formed;expected=terms->member_actor_ids;

    }
    if(action.participants!=expected||!unique(expected))return common_failure("MilitaryParticipantsMismatch");if(!finishing)for(auto& id:expected){auto actor=c.actor(id);if(!actor||actor->action_id!=action.id)return common_failure("MilitaryOccupationMissing");}if(action.kind=="army_form"){auto terms=std::get_if<ArmyFormationTerms>(&payload->terms);
        auto camp=get(cat.garrisons,terms->garrison_id);auto inv=c.inventory(terms->source_inventory_id);auto wallet=c.wallet(terms->source_wallet_id);if(!camp||!inv||!wallet||terms->money<0||terms->money>1000000)return common_failure("InvalidMilitarySupplyTerms");if(camp->inventory_id!=terms->source_inventory_id||camp->wallet_id!=terms->source_wallet_id||camp->organization_id!=terms->organization_id||!terms->ownership_id.empty())return common_failure("MilitarySupplySourceMismatch");Owner owner{Owner::Kind::organization,terms->organization_id,{}};bool reserved=false;for(auto& r:wallet->reserved)if(r.action_id==action.id&&r.amount==terms->money)reserved=true;if(!owner_equal(inv->owner,owner)||!owner_equal(wallet->owner,owner)||!reserved)return common_failure("MilitaryEscrowMismatch");for(auto& good:terms->goods){auto held=count_inventory_items(c,inv->id,good.first,{owner},ReservationRef{action.id});if(!held.ok)return {false,{},held.error};if(good.second<1||good.second>1000000||held.value!=good.second)return common_failure("MilitaryEquipmentReservationMismatch");}
    }return common_success();
}
}
